/bin/zsh -lc "cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk=0;
  reg rst_n=0;
  reg valid_in=0;
  reg [7:0] data_in=0;
  wire valid_out;
  wire [15:0] data_out;

  TopModule dut(
    .clk(clk), .rst_n(rst_n), .valid_in(valid_in), .data_in(data_in),
    .valid_out(valid_out), .data_out(data_out)
  );

  always #5 clk = ~clk;

  task send(input [7:0] d);
    begin
      @(negedge clk);
      valid_in = 1;
      data_in = d;
      @(negedge clk);
      valid_in = 0;
      data_in = 0;
    end
  endtask

  always @(posedge clk) begin
    $display("t=%0t rst_n=%0b vin=%0b din=%02h | vout=%0b dout=%04h flag=%0b data_r=%02h",
      $time, rst_n, valid_in, data_in, valid_out, data_out, dut.flag, dut.data_r);
  end

  initial begin
    repeat (2) @(negedge clk);
    rst_n = 1;
    send(8'"'h12);
    send(8'h34);
    repeat (2) @(negedge clk);
    send(8'hab);
    repeat (2) @(negedge clk);
    send(8'hcd);
    repeat (4) @(negedge clk);
    "'$finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

